import{_ as n,C as s,c as o,o as i,a3 as t,G as r}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Tax settings","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/taxes/tax-settings.md","filePath":"master/finance/taxes/tax-settings.md","lastUpdated":1792041590000}'),l={name:"master/finance/taxes/tax-settings.md"};function d(c,e,h,u,p,g){const a=s("ImagePopup");return i(),o("div",null,[e[0]||(e[0]=t('<h1 id="tax-settings" tabindex="-1">Tax settings <a class="header-anchor" href="#tax-settings" aria-label="Permalink to &quot;Tax settings&quot;">​</a></h1><p>The Manage Taxes page holds the company-wide rules for taxes: which taxes are the defaults, how tax amounts are rounded, and whether the prices you type already include tax.</p><blockquote><p><strong>In simple words:</strong> These are the global tax switches. Decide them before your first invoice.</p></blockquote><p>This page exists only in the <strong>Accounting</strong> app.</p><h2 id="open-the-page" tabindex="-1">Open the page <a class="header-anchor" href="#open-the-page" aria-label="Permalink to &quot;Open the page&quot;">​</a></h2><p><code>Accounting → Settings → Manage Taxes</code></p><p>If the page only shows a warning box, run <a href="./../get-started/accounting-setup.html">Set up accounting</a> first.</p>',7)),r(a,{src:"/images1/finance/settings_taxes.png",alt:"Accounting → Settings → Manage Taxes with Default Taxes, Rounding Method, Prices and Fiscal Country filled in"}),e[1]||(e[1]=t('<h2 id="change-the-settings" tabindex="-1">Change the settings <a class="header-anchor" href="#change-the-settings" aria-label="Permalink to &quot;Change the settings&quot;">​</a></h2><ol><li>Open <code>Accounting → Settings → Manage Taxes</code>.</li><li>Change the fields below.</li><li>Click <strong>Save changes</strong>.</li></ol><h3 id="default-taxes" tabindex="-1">Default Taxes <a class="header-anchor" href="#default-taxes" aria-label="Permalink to &quot;Default Taxes&quot;">​</a></h3><p>The page says: &quot;Default will be applied on products if no tax is selected.&quot;</p><ul><li><strong><em>Sales Tax:</em></strong> One of your <strong>Sale</strong> taxes. Sample: <code>15 %</code>.</li><li><strong><em>Purchase Tax:</em></strong> One of your <strong>Purchase</strong> taxes. Sample: <code>15 %</code>.</li></ul><h3 id="rounding-method" tabindex="-1">Rounding Method <a class="header-anchor" href="#rounding-method" aria-label="Permalink to &quot;Rounding Method&quot;">​</a></h3><p>&quot;Method used to round tax amounts.&quot;</p><ul><li><strong>Round Per Line:</strong> Aureus rounds the tax of each invoice line to the currency precision, then adds the lines up.</li><li><strong>Round Globally:</strong> Aureus adds the exact amounts and rounds at the end.</li></ul><p>Per line matches what a customer sees on each line. Globally avoids small rounding gaps on invoices with many lines.</p><h3 id="prices" tabindex="-1">Prices <a class="header-anchor" href="#prices" aria-label="Permalink to &quot;Prices&quot;">​</a></h3><p>Choose <strong>Default</strong>, <strong>Included</strong> or <strong>Excluded</strong>. It sets whether the prices you enter on products and invoices already contain tax.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This field is locked once the company has at least one invoice. Decide before you start.</p></div><h3 id="fiscal-country" tabindex="-1">Fiscal Country <a class="header-anchor" href="#fiscal-country" aria-label="Permalink to &quot;Fiscal Country&quot;">​</a></h3><p>The country where your company pays its taxes.</p><h2 id="tax-included-and-tax-excluded" tabindex="-1">Tax included and tax excluded <a class="header-anchor" href="#tax-included-and-tax-excluded" aria-label="Permalink to &quot;Tax included and tax excluded&quot;">​</a></h2><p>A price is <strong>tax excluded</strong> when the tax is added on top. A price is <strong>tax included</strong> when the tax is already inside it.</p><p>Example with a 15 % tax and a price of 115:</p><table tabindex="0"><thead><tr><th></th><th>Tax excluded</th><th>Tax included</th></tr></thead><tbody><tr><td>Untaxed amount</td><td>115.00</td><td>100.00</td></tr><tr><td>Tax</td><td>17.25</td><td>15.00</td></tr><tr><td>Total</td><td>132.25</td><td>115.00</td></tr></tbody></table><p>Two places control this:</p><ul><li>The <strong>Included in Price</strong> option on each <a href="./taxes.html">tax</a>. <strong>Included</strong> makes that tax price included.</li><li>The <strong>Prices</strong> setting on this page, as the company-wide choice.</li></ul><p>Use the option on the tax when one tax differs from the rest, for example when only your retail prices include tax.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./taxes.html">Taxes</a></li><li><a href="./tax-groups.html">Tax groups</a></li><li><a href="./fiscal-positions.html">Fiscal positions</a></li><li><a href="./../../sales/sales/products-prices/manage-products.html">Manage products</a></li></ul>',23))])}const f=n(l,[["render",d]]);export{m as __pageData,f as default};
